// WF-05 · Construcción del mensaje de aprobación.
//
// El analista tiene que poder decidir SIN salir de Slack y sin abrir otra
// herramienta. Si para entender la alerta hay que ir al SIEM, el
// Human-in-the-Loop no reduce la latencia: la multiplica.
//
// Por eso el mensaje incluye el rationale completo del motor de triaje: no
// 'puntuación 87', sino POR QUÉ 87.

const a = $input.first().json;
const t = a.triage ?? {};
const acciones = a.plan?.actions ?? [];

const resumenAcciones = acciones
  .map((ac) => `• \`${ac.action_type}\` sobre \`${ac.target}\` (${ac.platform}, caduca ${ac.expires_at})`)
  .join('\n');

const motivos = (t.rationale ?? []).map((r) => `• ${r}`).join('\n');

const bloques = [
  {
    type: 'header',
    text: { type: 'plain_text', text: `🚨 Aprobación requerida — ${a.asset?.host ?? 'host desconocido'}` },
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Puntuación:*\n${t.score}/100` },
      { type: 'mrkdwn', text: `*Criticidad del activo:*\n${a.asset?.criticality ?? 'desconocida'}` },
      { type: 'mrkdwn', text: `*Regla:*\n${a.rule?.name ?? '—'}` },
      { type: 'mrkdwn', text: `*Origen:*\n${a.source ?? '—'}` },
    ],
  },
  { type: 'section', text: { type: 'mrkdwn', text: `*Por qué:*\n${motivos || '—'}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Acciones propuestas:*\n${resumenAcciones || '—'}` } },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `alert_id \`${a.alert_id}\` · sin respuesta en 15 min se escala a guardia y *no se ejecuta nada*`,
      },
    ],
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        style: 'danger',
        text: { type: 'plain_text', text: 'Contener ahora' },
        // $execution.resumeUrl es la URL que genera el nodo Wait. Es un token
        // de un solo uso: quien la tenga puede reanudar esta ejecución y sólo
        // ésta, lo que hace innecesario autenticar el callback.
        url: `{{ $execution.resumeUrl }}?decision=approve&by={{ '{{user.name}}' }}`,
        value: 'approve',
        action_id: 'blinksec_approve',
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Ignorar' },
        url: `{{ $execution.resumeUrl }}?decision=reject&by={{ '{{user.name}}' }}`,
        value: 'reject',
        action_id: 'blinksec_reject',
      },
    ],
  },
];

return [{ json: { ...a, slackBlocks: bloques } }];

// WF-05 · Interpretación de la decisión.
//
// Decisión de diseño que no se negocia: el TIMEOUT ES RECHAZO.
//
// La alternativa —ejecutar la contención si nadie responde— convertiría el
// Human-in-the-Loop en un retardo de 15 minutos sin ningún control real. Si
// la evidencia bastara para actuar sin supervisión, no habríamos pedido
// aprobación. Que nadie conteste de madrugada no cambia esa evidencia.

const esperado = $('Construir mensaje Slack').first().json;
const reanudacion = $input.first().json;

// Al reanudar por webhook, n8n expone los parámetros de consulta. Si el nodo
// expiró por tiempo, no habrá ninguno.
const query = reanudacion.query ?? {};
const decision = query.decision ?? null;
const quien = query.by ?? null;

const aprobado = decision === 'approve';

return [
  {
    json: {
      ...esperado,
      aprobado,
      aprobadoPor: aprobado ? quien : null,
      decision: decision ?? 'timeout',
      decididoEn: new Date().toISOString(),
      motivoRechazo: decision === null ? 'sin respuesta humana en la ventana de 15 min' : null,
    },
  },
];
